	writer := multipart.NewWriter(form)
	formField, err := writer.CreateFormField("model")
	if err != nil {
		log.Fatal(err)
	}
	_, err = formField.Write([]byte("openai/gpt-image-2"))

	fw, err := writer.CreateFormFile("cat.png", filepath.Base("cat.png"))
	if err != nil {
		log.Fatal(err)
	}
	fd, err := os.Open("cat.png")
	if err != nil {
		log.Fatal(err)
	}
	defer fd.Close()
	_, err = io.Copy(fw, fd)
	if err != nil {
		log.Fatal(err)
	}

	formField, err = writer.CreateFormField("prompt")
	if err != nil {
		log.Fatal(err)
	}
	_, err = formField.Write([]byte("Добавь коту солнечные очки"))

	writer.Close()

	client := &http.Client{}
	req, err := http.NewRequest("POST", "https://api.timeweb.ai/v1/images/edits", form)
	if err != nil {
		log.Fatal(err)
	}
	req.Header.Set("Authorization", "Bearer " + os.Getenv("AI_GATEWAY_KEY"))
	req.Header.Set("Content-Type", writer.FormDataContentType())
	resp, err := client.Do(req)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	bodyText, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}
