import (
	"bytes"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
)

func main() {
	form := new(bytes.Buffer)
	writer := multipart.NewWriter(form)
	formField, err := writer.CreateFormField("purpose")
	if err != nil {
		log.Fatal(err)
	}
	_, err = formField.Write([]byte("batch"))

	formField, err = writer.CreateFormField("model")
	if err != nil {
		log.Fatal(err)
	}
	_, err = formField.Write([]byte("openai/gpt-4.1-mini"))

	fw, err := writer.CreateFormFile("batch.jsonl", filepath.Base("batch.jsonl"))
	if err != nil {
		log.Fatal(err)
	}
	fd, err := os.Open("batch.jsonl")
	if err != nil {
		log.Fatal(err)
	}
	defer fd.Close()
	_, err = io.Copy(fw, fd)
	if err != nil {
		log.Fatal(err)
	}

	writer.Close()

	client := &http.Client{}
	req, err := http.NewRequest("POST", "https://api.timeweb.ai/v1/files", form)
	if err != nil {
		log.Fatal(err)
	}
	req.Header.Set("Authorization", "Bearer " + os.Getenv("AI_GATEWAY_KEY"))
	req.Header.Set("Content-Type", writer.FormDataContentType())
	resp, err := client.Do(req)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	bodyText, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%s\n", bodyText)
}

